using System;
using DG.Tweening;
using LittleLeo;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class DiceMovement : MonoBehaviour
{
	private struct AnimationVariables
	{
		public Coroutine AnimationCoroutine;

		public Action AfterPositionedAction;
	}

	[Header("After Rolling Animation")]
	[SerializeField]
	private AnimationCurve afterRollingAnimCurve;

	[SerializeField]
	private float afterRollingAnimDuration;

	[SerializeField]
	private AnimationCurve afterRollingHeightCurve;

	[SerializeField]
	private float afterRollingHeight;

	[SerializeField]
	private AnimationCurve afterRollingRotationCurve;

	[Header("Dice In Hand Repositioning Animation")]
	[SerializeField]
	private AnimationCurve diceInHandRepositioningCurve;

	[SerializeField]
	private float diceInHandRepositioningDuration;

	[Header("Components")]
	[SerializeField]
	private DiceInstance diceInstance;

	[SerializeField]
	private Transform diceModelHolder;

	[SerializeField]
	private Transform diceModelRotationPivot;

	[SerializeField]
	private FloatReference diceRollingZPosition;

	[Header("Companions And Enemies")]
	[SerializeField]
	private FloatReference parallaxMovementAmountFloatReference;

	private AnimationVariables animationVariables;

	private TweenParams tweenParams;

	private float drawTurnPositionX;

	private float parallaxMovementAmount => parallaxMovementAmountFloatReference.Value;

	private int rolledDiceFaceIndex => diceInstance.RolledDiceFaceIndex;

	private bool dragging => diceInstance.Dragging;

	private Vector3 onHandDiceRotation => ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.DiceFaceRotation[rolledDiceFaceIndex];

	private void Update()
	{
		if (dragging)
		{
			base.transform.position = ReferenceSingleton<InputManager>.Instance.GetActionInstanceConvertedMousePosition();
		}
	}

	private void Start()
	{
		tweenParams = new TweenParams().SetEase(Ease.OutQuart);
	}

	public void SetDrawTurnPositionX(Vector3 position)
	{
		drawTurnPositionX = position.x;
	}

	public void OnStartPlayerTurn()
	{
		MoveDiceWithCameraParallax(parallaxMovementAmount);
	}

	public void OnStartEnemyTurn()
	{
		MoveDiceWithCameraParallax(0f - parallaxMovementAmount);
	}

	public void OnStartDrawTurn()
	{
		MoveDiceWithCameraParallax(0f);
	}

	private void MoveDiceWithCameraParallax(float amount)
	{
		if (diceInstance.DiceOwnerEnum != 0)
		{
			DOTween.Sequence().Append(base.transform.DOMoveX(drawTurnPositionX + amount, 1f).SetAs(tweenParams)).AppendCallback(delegate
			{
				diceInstance.SetOriginalPositionAsCurrentPositionX();
			});
		}
	}

	public void SetupDiceToRoll()
	{
		diceModelRotationPivot.localRotation = Quaternion.identity;
		diceModelHolder.localRotation = Quaternion.identity;
		MoveDiceToDiceRollingPosition();
	}

	private void MoveDiceToDiceRollingPosition()
	{
		base.transform.position = new Vector3(base.transform.position.x, base.transform.position.y, diceRollingZPosition.Value);
	}

	public void PlayAnimationAfterDiceDraw(Vector3 endPosition, float rotationX, float rotationZ, Action afterPositionedAction)
	{
		Debug.Log("Playing animation after dice draw", this);
		Quaternion diceModelRotationPivotStartRotation = diceModelRotationPivot.localRotation;
		Quaternion diceModelRotationPivotEndRotation = Quaternion.Euler(rotationX, 0f, rotationZ);
		Quaternion rotation = base.transform.rotation;
		base.transform.rotation = Quaternion.identity;
		diceModelHolder.rotation = rotation;
		Vector3 startPosition = base.transform.position;
		Quaternion diceModelHolderEndRotation = Quaternion.Euler(onHandDiceRotation);
		Quaternion diceModelHolderStartRotation = diceModelHolder.localRotation;
		Action<float, float> animationAction = delegate(float t, float v)
		{
			base.transform.position = Vector3.Lerp(startPosition, endPosition, v) + Vector3.up * afterRollingHeight * afterRollingHeightCurve.Evaluate(t);
			diceModelHolder.localRotation = Quaternion.Lerp(diceModelHolderStartRotation, diceModelHolderEndRotation, afterRollingRotationCurve.Evaluate(t));
			diceModelRotationPivot.localRotation = Quaternion.Lerp(diceModelRotationPivotStartRotation, diceModelRotationPivotEndRotation, diceInHandRepositioningCurve.Evaluate(t));
		};
		InnerPlayDiceMovementAnimation(afterRollingAnimDuration, afterRollingAnimCurve, animationAction, afterPositionedAction);
	}

	public void PlayGoBackToOriginalPositionAnimation(Vector3 endPosition, float animationDuration, AnimationCurve animationCurve, float rotationX, float rotationZ, Action afterPositionedAction)
	{
		Debug.Log("Playing go back to original position animation", this);
		Quaternion diceModelRotationPivotStartRotation = diceModelRotationPivot.localRotation;
		Quaternion diceModelRotationPivotEndRotation = Quaternion.Euler(rotationX, 0f, rotationZ);
		Vector3 startPosition = base.transform.position;
		Action<float, float> animationAction = delegate(float t, float v)
		{
			base.transform.position = Vector3.Lerp(startPosition, endPosition, v);
			diceModelRotationPivot.localRotation = Quaternion.Lerp(diceModelRotationPivotStartRotation, diceModelRotationPivotEndRotation, diceInHandRepositioningCurve.Evaluate(t));
		};
		InnerPlayDiceMovementAnimation(animationDuration, animationCurve, animationAction, afterPositionedAction);
	}

	public void PlayAdjustDicePositionInHand(Vector3 endPosition, float rotationX, float rotationZ)
	{
		Debug.Log("Playing adjust dice position in hand animation", this);
		Quaternion diceModelRotationPivotStartRotation = diceModelRotationPivot.localRotation;
		Quaternion diceModelRotationPivotEndRotation = Quaternion.Euler(rotationX, 0f, rotationZ);
		Vector3 startPosition = base.transform.position;
		Action<float, float> animationAction = delegate(float t, float v)
		{
			base.transform.position = Vector3.Lerp(startPosition, endPosition, v);
			diceModelRotationPivot.localRotation = Quaternion.Lerp(diceModelRotationPivotStartRotation, diceModelRotationPivotEndRotation, v);
		};
		InnerPlayDiceMovementAnimation(diceInHandRepositioningDuration, diceInHandRepositioningCurve, animationAction);
	}

	private void InnerPlayDiceMovementAnimation(float animationDuration, AnimationCurve animCurve, Action<float, float> animationAction, Action afterPositionedAction = null)
	{
		SetupAnimationVariables(afterPositionedAction);
		animationVariables.AnimationCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(CoroutineUtility.CurveRoutine(animationDuration, animCurve, delegate(float t, float v)
		{
			animationAction(t, v);
		}, delegate
		{
			diceInstance.SetDiceState(DiceState.OnHand);
			animationVariables.AfterPositionedAction?.Invoke();
			animationVariables.AnimationCoroutine = null;
		}));
	}

	public void StartFollowingMouseRotationAnimation()
	{
		SetupAnimationVariables(null);
		Quaternion diceModelRotationPivotStartRotation = diceModelRotationPivot.localRotation;
		Quaternion diceModelRotationPivotEndRotation = Quaternion.Euler(diceModelRotationPivot.localEulerAngles.x, 0f, 0f);
		animationVariables.AnimationCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(CoroutineUtility.CurveRoutine(diceInHandRepositioningDuration, diceInHandRepositioningCurve, delegate(float t, float v)
		{
			diceModelRotationPivot.localRotation = Quaternion.Lerp(diceModelRotationPivotStartRotation, diceModelRotationPivotEndRotation, v);
			animationVariables.AnimationCoroutine = null;
		}));
	}

	public void SetupAnimationVariables(Action afterPositionedAction)
	{
		if (animationVariables.AnimationCoroutine != null)
		{
			StopCoroutine(animationVariables.AnimationCoroutine);
			if (animationVariables.AfterPositionedAction == null)
			{
				animationVariables.AfterPositionedAction = afterPositionedAction;
			}
		}
		else
		{
			animationVariables.AfterPositionedAction = afterPositionedAction;
		}
	}

	public void RotateToNewDiceFace(float animationDuration, AnimationCurve animCurve)
	{
		Quaternion diceModelHolderStartRotation = diceModelHolder.rotation;
		Quaternion diceModelHolderEndRotation = Quaternion.Euler(onHandDiceRotation);
		ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(CoroutineUtility.CurveRoutine(animationDuration, animCurve, delegate(float t, float v)
		{
			diceModelHolder.localRotation = Quaternion.Lerp(diceModelHolderStartRotation, diceModelHolderEndRotation, afterRollingRotationCurve.Evaluate(t));
		}));
	}
}
